# Review package: 51b7323fc1c0ed431dad1c952932ad0dd878de22..HEAD

## Commits
7606160 Add greeting function with custom formatting
8bab44a Add greeting implementation plan

## Files changed
 greet.js      |  8 ++++++++
 greet.test.js | 35 +++++++++++++++++++++++++++++++++++
 plan.md       | 24 ++++++++++++++++++++++++
 3 files changed, 67 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..c56228a
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,8 @@
+function greet(name) {
+  if (!name) {
+    return 'Hello, guest! Welcome!';
+  }
+  return `Hello, ${name}! Welcome!`;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..4e1ae05
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,35 @@
+const { describe, it } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet.js');
+
+describe('greet', () => {
+  it('returns a formatted greeting for a normal name', () => {
+    const result = greet('Alice');
+    assert.strictEqual(result, 'Hello, Alice! Welcome!');
+  });
+
+  it('returns a formatted greeting for another name', () => {
+    const result = greet('Bob');
+    assert.strictEqual(result, 'Hello, Bob! Welcome!');
+  });
+
+  it('handles empty string gracefully', () => {
+    const result = greet('');
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles null input gracefully', () => {
+    const result = greet(null);
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles undefined input gracefully', () => {
+    const result = greet(undefined);
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+
+  it('handles no argument gracefully', () => {
+    const result = greet();
+    assert.strictEqual(result, 'Hello, guest! Welcome!');
+  });
+});
diff --git a/plan.md b/plan.md
new file mode 100644
index 0000000..3770877
--- /dev/null
+++ b/plan.md
@@ -0,0 +1,24 @@
+# Single-Task Greeting Plan
+
+**Spec:** Add a small greeting customization feature.
+
+**Goal:** The app can greet a provided name with custom formatting.
+
+---
+
+### Task 1: Add basic greeting function
+
+**Files:**
+- Create: `greet.js`
+- Create: `greet.test.js`
+
+**Acceptance Criteria:**
+- greet(name) returns a formatted greeting string.
+- The default behavior handles empty input gracefully.
+- Tests cover both normal and edge cases.
+
+- [ ] **Step 1: Implement greet function in greet.js**
+- [ ] **Step 2: Add tests for greet in greet.test.js**
+- [ ] **Step 3: Run tests to verify**
+
+---

